      const r = runWithFakeGh(
        scriptPath("guard_comment_during_run.ts"),
        ["--number", "9", "--comment-id", "101", "--commenter", "octocat"],
        {
          cwd: configDir,
          env: { GITHUB_REPOSITORY: "owner/repo" },
          rules: [
            ...threadAs([
              ["/engineer", true],
              ["just a remark", true],
            ]),
            { match: ["api", "DELETE"] },
            { match: ["issue", "comment"] },
          ],
